static inline void const* error_downcast(ErrorBase const* error, ErrorVt const* vt) {
    for (ErrorVt const* error_vt = error->vt; error_vt; error_vt = error_vt->super) {
        if (error_vt == vt) return error;
    }
    return nullptr;
}

extern ErrorVt const ErrorBaseVt;

extern ErrorVt const StringErrorVt;
struct StringError {
    ErrorBase error;
    cstr message;
};
ErrorBase* string_error_new(cstr message);

extern ErrorVt const ErrorCollectionVt;
typedef struct ErrorCollection ErrorCollection;
void add_error_to_collection(FailableResult* collection, ErrorBase* error);

// The goal of this is to support `return ok(value_of_currect_type);` in functions that logically return something and
// `return ok;` in functions that logically return void, but not support the alternative form in either. Logical return
// type (the output paramter) is distinct from actual return type (always FailableResult for failable functions)

// To accomplish this several macros and static globals are used. See their exact values below. `ok` is a standard (not
// function-like) macro. _OK_INTERNAL is a function-like macro *and also* a const global FailableResult.
// _OUTPUT_PARAM is the name of the output param in functions that logically return a value, *and also* a global that
// points to a FailableResult. The value of _GLOBAL_RETURNED_VALUE_TARGET is unimportant, it should never be read from,
// but the global _OUTPUT_PARAM needs something mutable to point to.

// The `return ok;` case expands to:
// ```
// return *(_OUTPUT_PARAM) = _OK_INTERNAL;
// ```
// Which is a bit convoluted, but valid if the function logically returns nothing. `_OUTPUT_PARAM` and `_OK_INTERNAL`
// are both globals, a FailableResult* and const FailableResult respectively. The function thus always returns the
// global _OK_INTERNAL value (null error). The fact that it sets *_OUTPUT_PARAM is unimportant *unless* the function
// logically returns something. In this case the global _OUTPUT_PARAM will be shadowed by a parameter, which will
// presumably be of a type other than FailableResult*. Assigning a FailableResult to *_OUTPUT_PARAM should then produce
// a type error.

// On the other hand the `return ok(foo);` case expands to:
// ```
// // return *(_OUTPUT_PARAM) = _OK_INTERNAL(foo);
// // but _OK_INTERNAL is a function-like macro, so it continues expanding:
// return *(_OUTPUT_PARAM) = (foo), (FailableResult){nullptr};
// ```
// This assigns *_OUTPUT_PARAM to the given value, and then returns a null error result using the comma operator. This
// works if the function logically returns the given type (_OUTPUT_PARAM is a parameter that points to the right type)
// but type errors if the function logically returns a different type (trivial) or nothing (_OUTPUT_PARAM is a global
// that points to a FailableResult, which hopefully isn't the type of foo).

static FailableResult _GLOBAL_RETURNED_VALUE_TARGET = {nullptr};
static FailableResult* const _OUTPUT_PARAM = &_GLOBAL_RETURNED_VALUE_TARGET;
static FailableResult const _OK_INTERNAL = {nullptr};
#define ok *(_OUTPUT_PARAM) = _OK_INTERNAL // if changing, don't forget to update generic/hmap.h and generic/set.h
#define _OK_INTERNAL(...) (__VA_ARGS__), (FailableResult){nullptr}

// Turn any expression into a result, with the error automatically generated by stringifying the expression
#define ok_if(expr) (FailableResult){(expr) ? nullptr : string_error_from_str(#expr " failed")}

static inline ErrorBase* string_error_from_str(const char* message) { return string_error_new(cstr_from(message)); }
static inline ErrorBase* string_error_from_csview(csview message) { return string_error_new(cstr_from_sv(message)); }
static inline ErrorBase* error_base_verify(ErrorBase* error) {
    return error ? error : string_error_from_csview(c_sv("Error(nullptr)"));
}
#define err(value) (FailableResult){.error = _Generic((value), \
    const char*: string_error_from_str, \
    char*: string_error_from_str, \
    cstr: string_error_new, \
    csview: string_error_from_csview, \
    ErrorBase*: error_base_verify \
)(value)}
#define err_d(...) (FailableResult){ \
    .error = string_error_new(display_into_cstr(display_sequence(DEFAULT_DISPLAY, __VA_ARGS__))) \
}

#ifndef FAILABLE_TRY_INITIALIZER
#define FAILABLE_TRY_INITIALIZER = {0}
#endif

// Each try () ... statement needs to terminate with a bubble, cleanup {}, if_err (err) {}, or_panic, or_log(type),
// or or_ignore
// clause. before that there may be if_ok {} or if_err (Type, err) clauses. Because I don't think surrounding code blocks
// in () looks nice, the blocks themselves are not consumed by a macro. Therefore I need to get fancy to guarantee at
// compile time the correct syntax is used.

// The try () ... statement is expanded out to a for loop with a non-braced if/else body. The non-terminating else if
// arms are each non-braced and contain a do/while (0) loop. Each try clause macro closes the previous do/while loop
// and opens a new one (if it's non-terminating), thus forcing a terminating clause to come last and preventing multiple
// terminating clauses. Of course a while(...); after a try statement could break it, but that's unlikely to happen by
// accident.

// The outer for loop is for two reasons. First, it allows us to declare a variable (in this case an anonymous struct)
// containing two values) in the scope of the following statement. Second, it needs to perform two iterations for the
// cleanup {} clause. Cleanup must execute its code block *and then* return. It is therefore implemented as two else if
// arms, the first (to run) of which sets _i.i to -2, which is then bumped to -1 by the for loop, which then triggers
// the second (to run) arm, which returns. cleanup {} can't contain it's own loop, and if/else, because then we'd have
// multiple layers of unbraced else which the compiler generates warnings about.

#ifndef try
#define try(...) c_MACRO_OVERLOAD(_FAILABLE_TRY, __VA_ARGS__)
#endif
#define _FAILABLE_TRY_1(expr) \
    for (struct {\
            FailableResult result; \
            bool exit; \
            bool cleanup_done; \
            bool conditional_done; \
            bool unconditional_done; \
            void const* tmp; \
    } _current_result = {.result = (expr)}; !_current_result.exit; ) if (0) do {}
#define _FAILABLE_TRY_2(init, expr) init FAILABLE_TRY_INITIALIZER; _FAILABLE_TRY_1(expr)
#define if_ok while (0); else if \
    (!_current_result.result.error && !_current_result.conditional_done && (_current_result.conditional_done = true)) do
#define unconditional while (0); else if (\
    !_current_result.unconditional_done && (_current_result.unconditional_done = true)) do
#define bubble while (0); \
    else if (!_current_result.result.error) { _current_result.exit = true; } \
    else return _current_result.result
#define cleanup while (0); \
    else if (_current_result.result.error && _current_result.cleanup_done) { return _current_result.result; } \
    else if (_current_result.cleanup_done = true, !_current_result.result.error) { _current_result.exit = true; } else
#define if_err(...) c_MACRO_OVERLOAD(_FAILABLE_IF_ERR, __VA_ARGS__)
#define _FAILABLE_IF_ERR_1(er) while (0); \
    else if ((_current_result.exit = true), _current_result.conditional_done || !_current_result.result.error) {} \
    else for (ErrorBase const* er = _current_result.result.error; \
              er; \
              error_base_destroy(_current_result.result.error), er = nullptr)
#define _FAILABLE_IF_ERR_2(type, er) while (0); \
    else if (_current_result.result.error && \
             !_current_result.conditional_done && \
             (_current_result.tmp = error_downcast(_current_result.result.error, &type##Vt)) && \
             (_current_result.conditional_done = true)) \
        for (type const* er = _current_result.tmp; \
             er; \
             error_base_destroy(_current_result.result.error), _current_result.result.error = nullptr, er = nullptr) do
#define or_collect_into(collection) if_err (er) add_error_to_collection(collection, current_error_move())
#define or_panic if_err (er) panic_from_error(er)
#define or_log(type) if_err (er) log_##type(er)
#define or_ignore if_err (er) {}

static inline ErrorBase* error_base_pointer_move(ErrorBase** ptr) {
    ErrorBase* tmp = *ptr;
    *ptr = nullptr;
    return tmp;
}
#define current_error_base ((ErrorBase const*)_current_result.result.error)
#define current_error_move() error_base_pointer_move(&_current_result.result.error)
#define current_error_destroy() error_base_destroy(current_error_move())

#define try_return(...) c_MACRO_OVERLOAD(_FAILABLE_TRY_RETURN, __VA_ARGS__)
#define _FAILABLE_TRY_RETURN_1(expr) \
    do { \
        _FAILABLE_TRY_1(expr) bubble; \
        return ok; \
    } while(0)
#define _FAILABLE_TRY_RETURN_2(ret_name, expr) \
    do { \
        _FAILABLE_TRY_2(typeof(*_OUTPUT_PARAM) ret_name, expr) bubble; \
        return ok(ret_name); \
    } while(0)
